#!/usr/bin/env bash
set -euo pipefail
O="${1:-/var/tmp}"; T="${K3S_PV_RESTIC_TAG:-k3s-persistent-volumes}"; R="${K3S_PV_ROOT:-/mnt/store1/k3s/local-path}"; X="$(mktemp -d /var/tmp/k3s-pv-export.XXXXXX)"; trap 'rm -rf "$X"' EXIT; [[ ${EUID} -eq 0 ]] || exit 1; set -a; source /etc/k3s-backup/r2.env; set +a; export RESTIC_PASSWORD_FILE=/etc/k3s-backup/restic.password RESTIC_REPOSITORY="$(cat /etc/k3s-backup/restic.repository)"; j="$(restic snapshots --tag "$T" --json|python3 -c 'import json,sys,datetime;x=json.load(sys.stdin);s=max(x,key=lambda v:datetime.datetime.fromisoformat(v["time"].replace("Z","+00:00"))) if x else None;print(json.dumps({"id":s["id"],"time":s["time"]}) if s else "")')"; [[ -n "$j" ]] || exit 1; i="$(python3 -c 'import json,sys;print(json.loads(sys.argv[1])["id"])' "$j")"; t="$(python3 -c 'import json,sys;print(json.loads(sys.argv[1])["time"])' "$j")"; restic restore "$i" --target "$X"; S="$X$R"; [[ -d "$S" ]] || exit 1; install -d -m 0755 "$O"; a="k3s-persistent-volumes-$(date -u +%Y%m%dT%H%M%SZ)-${i:0:8}.tar.gz"; tar --numeric-owner -C "$S" -czf "$O/$a" .; (cd "$O"; sha256sum "$a" >"$a.sha256"; sha256sum -c "$a.sha256"); printf 'format=k3s-pv-archive-v1\nsnapshot_id=%s\nsnapshot_time=%s\nsource_root=%s\ncreated_at=%s\n' "$i" "$t" "$R" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" >"$O/$a.metadata"; chmod 0600 "$O/$a" "$O/$a.sha256" "$O/$a.metadata"; echo "snapshot=$i"; echo "snapshot_time=$t"; echo "archive=$O/$a"
